export default function drawChart(category, stats, ctx, Chart) {
    var myChart = new Chart(ctx, {
	type: 'bar',
	data: {
	    labels: ['Animal Alarmist', 'Animal Critic', 'Animal Agnostic', 'Animal Advocate', 'True Forest Friend'],
	    datasets: [{
		label: '# of Votes',
		data: [12, 80, 12, 5, 60],
		backgroundColor: [
		    'rgba(255, 99, 132, 0.2)',
		    'rgba(54, 162, 235, 0.2)',
		    'rgba(255, 206, 86, 0.2)',
		    'rgba(75, 192, 192, 0.2)',
		    'rgba(153, 102, 255, 0.2)',
		],
		borderColor: [
		    'rgba(255, 99, 132, 1)',
		    'rgba(54, 162, 235, 1)',
		    'rgba(255, 206, 86, 1)',
		    'rgba(75, 192, 192, 1)',
		    'rgba(153, 102, 255, 1)',
		],
		borderWidth: 1
	    }]
	},
	options: {
	    scales: {
		yAxes: [{
		    ticks: {
			beginAtZero: true,
			padding: 20
		    }
		}]
	    }
	}
    });
}
